ro-suite-nav { --ro-suite-content-max-width: 1320px; --ro-suite-inline-padding: 28px; }
ro-suite-nav > nav { box-sizing: border-box; max-width: var(--ro-suite-content-max-width); margin: 0 auto; min-height: 52px; padding: 4px var(--ro-suite-inline-padding); display: flex; align-items: center; }
